using System.Security.Principal;
using System.Text.Json;
using Microsoft.Win32;
namespace CodexLight.Migration;
public static class ManualPlan {
 static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true,WriteIndented=true};
 static T Read<T>(string path)=>JsonSerializer.Deserialize<T>(File.ReadAllText(MigrationStorage.Canonical(path)),Json)??throw new IOException("Plan evidence absent");
 internal static StageReceipt LoadBoundPlan(string path,string expectedSha){if(expectedSha.Length!=64||MigrationCoordinator.Hash(MigrationStorage.Canonical(path))!=expectedSha.ToLowerInvariant())throw new IOException("Trusted handoff plan hash required/mismatched");return Read<StageReceipt>(path);}
 internal static void ValidateLink(StageReceipt plan,StageReceipt failed,string failedHash){ManualReconcile.RequireFailedSource(failed);if(plan.Phase!="ManualHandoffPlanned"||plan.SourceFailedReceiptSha256!=failedHash||plan.Legacy!=failed.Legacy||plan.NewRoot!=failed.NewRoot||plan.Recovery!=failed.Recovery||!string.IsNullOrEmpty(plan.HandoffPlan)||!string.IsNullOrEmpty(plan.HandoffPlanSha256)||Version.Parse(plan.Target)<Version.Parse(failed.Legacy.Version)||new[]{plan.ManifestSha256,plan.SetupSha256,plan.SourceFailedReceiptSha256,plan.PreHandoffSnapshotSha256}.Any(x=>x.Length!=64||!x.All(Uri.IsHexDigit)))throw new IOException("Replacement package lacks exact authorized plan chain");}
 public static void Verify(StageReceipt plan){var source=MigrationStorage.Canonical(plan.SourceFailedReceipt);if(Path.GetDirectoryName(source)!=plan.Recovery)throw new IOException("Original receipt outside plan recovery root");ValidateLink(plan,Read<StageReceipt>(source),MigrationCoordinator.Hash(source));var snapshot=MigrationStorage.Canonical(plan.PreHandoffSnapshot);if(Path.GetDirectoryName(snapshot)!=plan.Recovery||!(Path.GetFileName(snapshot)=="data"||Path.GetFileName(snapshot).StartsWith("manual-plan-data-",StringComparison.Ordinal)))throw new IOException("Plan backup outside recovery scope");if(MigrationCoordinator.Hash(snapshot+".manifest.json")!=plan.PreHandoffSnapshotSha256)throw new IOException("Plan backup manifest changed");var data=Read<DataSnapshot>(snapshot+".manifest.json");if(!data.SourceRoot.Equals(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexLight"),StringComparison.OrdinalIgnoreCase))throw new IOException("Plan backup source outside app data");MigrationStorage.VerifySnapshot(data,snapshot);if(MigrationCoordinator.Hash(Path.Combine(plan.Recovery,"legacy.msi"))!=plan.Legacy.SourceSha256)throw new IOException("Plan original MSI backup changed");}
 public static void Prepare(string failedReceipt,string manifest,string manifestHash,string setupHash,bool authorize,bool tasksCompleted){SafeStage.Execute(manifest,manifestHash,setupHash,false,true,false);failedReceipt=MigrationStorage.Canonical(failedReceipt);var failed=Read<StageReceipt>(failedReceipt);ManualReconcile.RequireFailedSource(failed);SafeRetire.ValidateReceipt(failed with{Phase="StagedOldPreserved"},failedReceipt,failed.ManifestSha256,failed.SetupSha256);if(MsiProbe.ReadCurrentUser()!=failed.Legacy)throw new IOException("Original MSI changed");var m=Read<StageRelease>(manifest);var baseline=Read<DataSnapshot>(Path.Combine(failed.Recovery,"data.manifest.json"));var expected=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexLight");if(!baseline.SourceRoot.Equals(expected,StringComparison.OrdinalIgnoreCase))throw new IOException("Wrong baseline source");MigrationStorage.VerifySnapshot(baseline,Path.Combine(failed.Recovery,"data"));if(MigrationCoordinator.Hash(Path.Combine(failed.Recovery,"legacy.msi"))!=failed.Legacy.SourceSha256)throw new IOException("Original MSI backup mismatch");
 void NoTarget(){if(Directory.Exists(failed.NewRoot)||File.Exists(failed.NewRoot))throw new IOException("Destination exists: do not prepare a replacement installer plan");using var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\CodexLightDesktop");if(key!=null)throw new IOException("Destination registration exists");}NoTarget();if(!authorize){Console.WriteLine("PLAN INSPECT ONLY: no new installation, receipt or backup written");return;}if(!tasksCompleted)throw new IOException("Task completion confirmation required");
 var sid=WindowsIdentity.GetCurrent().User?.Value??throw new IOException("SID missing");var options=new NamedWaitHandleOptions{CurrentUserOnly=true,CurrentSessionOnly=true};using var desktop=new Mutex(true,"CodexLight.Desktop."+sid,options,out bool first);if(!first)throw new IOException("Exit app normally before preparing handoff");try{using var locks=MigrationStorage.AcquireInstallRoots(failed.Legacy.InstallRoot,failed.NewRoot);SafeStage.Idle(failed.Legacy.InstallRoot,failed.NewRoot);NoTarget();var failedHash=MigrationCoordinator.Hash(failedReceipt);var current=MigrationStorage.CaptureApplicationData();bool reuse=JsonSerializer.Serialize(current)==JsonSerializer.Serialize(baseline);var id=Guid.NewGuid().ToString("N");var backup=Path.Combine(failed.Recovery,reuse?"data":"manual-plan-data-"+id);if(!reuse){if(new DriveInfo(Path.GetPathRoot(backup)!).AvailableFreeSpace<MigrationStorage.RequiredBytes(current,0,0,0))throw new IOException("Insufficient updated backup space");MigrationStorage.CopySnapshot(current,backup);}MigrationStorage.VerifySnapshot(reuse?baseline:current,backup);if(MsiProbe.ReadCurrentUser()!=failed.Legacy||MigrationCoordinator.Hash(failedReceipt)!=failedHash)throw new IOException("Old identity/evidence changed");NoTarget();var plan=failed with{Phase="ManualHandoffPlanned",ManifestSha256=manifestHash,SetupSha256=setupHash,Target=m.Version,SourceFailedReceipt=failedReceipt,SourceFailedReceiptSha256=failedHash,PreHandoffSnapshot=backup,PreHandoffSnapshotSha256=MigrationCoordinator.Hash(backup+".manifest.json")};Verify(plan);var output=Path.Combine(failed.Recovery,"manual-plan-"+id+".json");MigrationStorage.AtomicReceipt(output,plan);Console.WriteLine(JsonSerializer.Serialize(new{Plan=output,TrustedPlanSha256=MigrationCoordinator.Hash(output),ReusedVerifiedBackup=reuse,PackageManifestSha256=manifestHash,SetupSha256=setupHash,OldMsiRetained=true},Json));}finally{desktop.ReleaseMutex();}}
}
